#!/usr/bin/env bash
#
# START modification - generated by AI (GitHub Copilot, DeepSeek V4 Flash)
#
# merge-test.sh — offline end-to-end checks for the DB conflict-merge feature.
#
# Drives the UPM app on the emulator against a local WebDAV server and asserts
# the resulting database bytes for the scenarios in
# docs/database-conflict-merge-plan.md (§6).
#
# Everything is wrapped in a bash script on purpose: the interactive shell on
# the dev box is fish, where inline heredocs and long && chains with redirection
# fail. Menus are opened with the MENU key (reliable) instead of tapping the
# overflow button.
#
# Usage:
#   scripts/merge-test.sh up                 boot emulator + start WebDAV server
#   scripts/merge-test.sh seed LOCAL [BASE]  install files/upm.db / .sync-base
#   scripts/merge-test.sh remote DB|-        push DB to the remote (or delete it)
#   scripts/merge-test.sh unlock             launch the app and unlock it
#   scripts/merge-test.sh sync               trigger Sync from the overflow menu
#   scripts/merge-test.sh accounts           list the account names on screen
#   scripts/merge-test.sh status             print remote / local / base md5s
#   scripts/merge-test.sh row N              run matrix row N (1, 2, 8, 9)
#   scripts/merge-test.sh all                run the rows this script supports
#
# Artifacts (see §8 of the plan) default to /tmp, override with ART_DIR:
#   B0.db  base state      {test}                (contains the WebDAV settings)
#   L1.db  local change    {test, localacc}
#
# Environment overrides: SERIAL, ART_DIR, WEBDAV_PORT, DB_PASSWORD_FILE,
# REMOTE_PASSWORD_FILE.
#
set -euo pipefail

SERIAL="${SERIAL:-emulator-5554}"
APP_ID="com.u17od.upm"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
UI_PY="$SCRIPT_DIR/upm-ui.py"
WD_PY="$SCRIPT_DIR/webdav-test.py"
WD_SERVER_PY="$SCRIPT_DIR/webdav-test-server.py"
DB_PASSWORD_FILE="${DB_PASSWORD_FILE:-$SCRIPT_DIR/test.db.password}"
REMOTE_PASSWORD_FILE="${REMOTE_PASSWORD_FILE:-/tmp/remote.pw}"
WEBDAV_ROOT="${WEBDAV_ROOT:-/tmp/webdav-root}"
WEBDAV_PORT="${WEBDAV_PORT:-8080}"
HOST_URL="http://127.0.0.1:${WEBDAV_PORT}/upm/"
ART_DIR="${ART_DIR:-/tmp}"
UI_XML="/tmp/merge-ui.xml"

PASS=0
FAIL=0

adb_()  { adb -s "$SERIAL" "$@"; }
ui()    { python3 "$UI_PY" --serial "$SERIAL" "$@"; }
step()  { printf '\n== %s ==\n' "$*"; }
info()  { printf '   %s\n' "$*"; }
die()   { printf '[error] %s\n' "$*" >&2; exit 1; }

ok()    { PASS=$((PASS + 1)); printf '   [PASS] %s\n' "$*"; }
bad()   { FAIL=$((FAIL + 1)); printf '   [FAIL] %s\n' "$*"; }

focus() { adb_ shell dumpsys window | grep -m1 mCurrentFocus || true; }

dump_ui() {
    adb_ shell uiautomator dump /sdcard/ui.xml >/dev/null 2>&1
    adb_ shell cat /sdcard/ui.xml > "$UI_XML"
}

# ui_find text "<label>" [index]   -> "X Y" of the matching node
# ui_find class "<substr>" [index] -> "X Y" of the matching node
# index selects among several matches (default 0); e.g. the password field of
# the edit form is class EditText index 2 (name, user, password, url, notes).
ui_find() {
    local mode="$1" value="$2" index="${3:-0}"
    dump_ui
    python3 - "$mode" "$value" "$index" <<'PY'
import sys
import xml.etree.ElementTree as ET

mode, value, index = sys.argv[1], sys.argv[2], int(sys.argv[3])

def box(bounds):
    return [int(v) for v in bounds.strip('[]').replace('][', ',').split(',')]

matches = []
for node in ET.parse('/tmp/merge-ui.xml').getroot().iter('node'):
    text = node.get('text') or ''
    cls = node.get('class') or ''
    if (mode == 'text' and text == value) or (mode == 'class' and value in cls):
        l, t, r, b = box(node.get('bounds'))
        matches.append(((l + r) // 2, (t + b) // 2))

if index >= len(matches):
    sys.exit(3)
print(*matches[index])
PY
}

tap_text() {
    local xy
    xy="$(ui_find text "$1")" || die "no on-screen element '$1'"
    adb_ shell input tap $xy
}

# ---------------------------------------------------------------- commands
cmd_up() {
    mkdir -p "$WEBDAV_ROOT/upm"
    [[ -f "$REMOTE_PASSWORD_FILE" ]] || echo dummy > "$REMOTE_PASSWORD_FILE"
    if ! pgrep -f "webdav-test-server.py.*--port $WEBDAV_PORT" >/dev/null 2>&1; then
        step "Starting local WebDAV server on :$WEBDAV_PORT"
        nohup python3 "$WD_SERVER_PY" --root "$WEBDAV_ROOT" --port "$WEBDAV_PORT" \
            >/tmp/webdav-server.log 2>&1 &
        sleep 1
    else
        info "WebDAV server already running"
    fi
    if ! adb_ get-state >/dev/null 2>&1; then
        step "Booting emulator (swiftshader)"
        EMULATOR_GPU=swiftshader_indirect "$SCRIPT_DIR/emulator-run.sh"
    else
        info "Emulator already running"
    fi
    adb_ shell svc power stayon true
}

cmd_remote() {
    local db="$1" args
    args=(--url "$HOST_URL" --user test --password-file "$REMOTE_PASSWORD_FILE")
    if [[ "$db" == "-" ]]; then
        python3 "$WD_PY" delete "${args[@]}" --db "$ART_DIR/B0.db" \
            --db-password-file "$DB_PASSWORD_FILE"
    else
        [[ -f "$db" ]] || die "no such db: $db"
        local pw="$db.password"
        [[ -f "$pw" ]] || pw="$DB_PASSWORD_FILE"
        python3 "$WD_PY" push "${args[@]}" --db "$db" --db-password-file "$pw"
    fi
}

cmd_seed() {
    local local_db="$1" base_db="${2:-}"
    [[ -f "$local_db" ]] || die "no such db: $local_db"
    adb_ shell am force-stop "$APP_ID"
    adb_ shell "run-as $APP_ID sh -c 'cat > files/upm.db'" < "$local_db"
    adb_ shell "run-as $APP_ID sh -c 'rm -f files/upm.db.sync-base files/upm*.tmp files/upm.db.conflict-*'"
    if [[ -n "$base_db" ]]; then
        [[ -f "$base_db" ]] || die "no such base: $base_db"
        adb_ shell "run-as $APP_ID sh -c 'cat > files/upm.db.sync-base'" < "$base_db"
        info "seeded local=$local_db base=$base_db"
    else
        info "seeded local=$local_db base=<none>"
    fi
}

cmd_unlock() {
    local attempt xy
    adb_ shell am start -n "$APP_ID/.AppEntryActivity" >/dev/null
    sleep 3
    for attempt in 1 2 3; do
        [[ "$(focus)" == *FullAccountList* ]] && { info "unlocked"; return 0; }
        if [[ "$(focus)" == *EnterMasterPassword* ]]; then
            xy="$(ui_find class EditText)" || { sleep 2; continue; }
            adb_ shell input tap $xy
            sleep 1
            ui clear
            ui type "$(cat "$DB_PASSWORD_FILE")"
            sleep 1
            tap_text "Open"
        fi
        sleep 3
    done
    [[ "$(focus)" == *FullAccountList* ]] && { info "unlocked"; return 0; }
    die "unlock failed: $(focus)"
}

cmd_sync() {
    adb_ shell input keyevent 82   # KEYCODE_MENU opens the overflow menu
    sleep 2
    tap_text "Sync"
    local i f
    for i in $(seq 1 10); do
        f="$(focus)"
        [[ "$f" == *SyncDatabase* || "$f" == *EnterMasterPassword* ]] && break
        sleep 1
    done
    [[ "$f" == *EnterMasterPassword* ]] && die "sync requested a password"
    for i in $(seq 1 40); do
        f="$(focus)"
        [[ "$f" != *SyncDatabase* ]] && { info "sync finished"; return 0; }
        sleep 1
    done
    die "sync did not finish"
}

local_md5() { adb_ exec-out run-as "$APP_ID" cat files/upm.db 2>/dev/null | md5sum | awk '{print $1}'; }
base_md5()  { adb_ exec-out run-as "$APP_ID" cat files/upm.db.sync-base 2>/dev/null | md5sum | awk '{print $1}'; }
remote_md5(){ md5sum "$WEBDAV_ROOT/upm/upm.db" 2>/dev/null | awk '{print $1}'; }
file_md5()  { md5sum "$1" | awk '{print $1}'; }

cmd_accounts() { ui dump | grep -vE '^UPM |More options' ; }

cmd_status() {
    printf '   remote: %s\n' "$(remote_md5)"
    printf '   local : %s\n' "$(local_md5)"
    printf '   base  : %s\n' "$(base_md5)"
}

# ---------------------------------------------------------------- UI helpers
# These build variant databases through the app itself (there is no CLI writer
# for the encrypted format). Each one first syncs a no-op so the 5-minute
# isSyncRequired edit guard is satisfied.

pull_db() {
    adb_ exec-out run-as "$APP_ID" cat files/upm.db > "$1"
    [[ -n "${2:-}" ]] && cp "$2" "$1.password"
    info "captured $1 ($(file_md5 "$1"))"
}

cmd_addaccount() {
    local out="$1" name="$2" base="${3:-$ART_DIR/B0.db}"
    cmd_seed "$base" "$base"
    cmd_remote "$base"
    cmd_unlock
    cmd_sync
    adb_ shell input keyevent 82; sleep 2
    tap_text "Add"; sleep 2
    adb_ shell input tap $(ui_find class EditText)
    ui type "$name"
    tap_text "Save"
    sleep 2
    pull_db "$out" "$base.password"
}

# edit FIELD (0=name 1=user 2=password 3=url 4=notes) of ACCOUNT in BASE.
cmd_edit() {
    local out="$1" base="$2" account="$3" field="$4" value="$5"
    cmd_seed "$base" "$base"
    cmd_remote "$base"
    cmd_unlock
    cmd_sync
    tap_text "$account"; sleep 1
    adb_ shell input keyevent 82; sleep 2
    tap_text "Edit"; sleep 2
    adb_ shell input tap $(ui_find class EditText "$field")
    ui clear
    ui type "$value"
    tap_text "Save"
    sleep 2
    pull_db "$out" "$base.password"
}

cmd_deleteaccount() {
    local out="$1" base="$2" account="$3"
    cmd_seed "$base" "$base"
    cmd_remote "$base"
    cmd_unlock
    cmd_sync
    tap_text "$account"; sleep 1
    adb_ shell input keyevent 82; sleep 2
    tap_text "Delete"; sleep 2
    tap_text "Yes"; sleep 2
    pull_db "$out" "$base.password"
}

# ---------------------------------------------------------------- matrix rows
run_row1() {
    step "Row 1 — remote changed only → download"
    cmd_seed "$ART_DIR/B0.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/L1.db"
    cmd_unlock; cmd_sync
    [[ "$(local_md5)" == "$(remote_md5)" ]] && ok "local == remote after download" \
        || bad "local ($(local_md5)) != remote ($(remote_md5))"
    ui dump | grep -q 'localacc' && ok "downloaded account present" \
        || bad "localacc missing"
}

run_row2() {
    step "Row 2 — local changed only → upload"
    cmd_seed "$ART_DIR/L1.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/B0.db"
    cmd_unlock; cmd_sync
    [[ "$(local_md5)" == "$(remote_md5)" ]] && ok "remote == local after upload" \
        || bad "remote ($(remote_md5)) != local ($(local_md5))"
    ui dump | grep -q 'localacc' && ok "local change preserved" || bad "localacc missing"
}

run_row8() {
    step "Row 8 — no base → LWW fallback + conflict backup"
    cmd_seed "$ART_DIR/L1.db"          # no base
    cmd_remote "$ART_DIR/B0.db"
    cmd_unlock; cmd_sync
    adb_ shell run-as "$APP_ID" ls files/ | grep -q 'upm.db.conflict-' \
        && ok "conflict backup file written" || bad "no conflict backup file"
    [[ "$(local_md5)" == "$(remote_md5)" ]] && ok "converged after fallback upload" \
        || bad "not converged"
}

run_row9() {
    step "Row 9 — up to date → no transfer"
    cmd_seed "$ART_DIR/B0.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/B0.db"
    cmd_unlock
    local before; before="$(remote_md5)"
    cmd_sync
    [[ "$(remote_md5)" == "$before" ]] && ok "remote untouched" || bad "remote changed"
    [[ "$(base_md5)" == "$(local_md5)" ]] && ok "base == local" || bad "base != local"
}

run_row3() {
    step "Row 3 — both sides added different accounts → union merge"
    require "$ART_DIR/R2.db"
    cmd_seed "$ART_DIR/L1.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/R2.db"
    cmd_unlock; cmd_sync
    [[ "$(local_md5)" == "$(remote_md5)" ]] && ok "merged uploaded (converged)" \
        || bad "not converged"
    local names; names="$(ui dump)"
    grep -q 'localacc' <<<"$names" && ok "local account kept" || bad "localacc missing"
    grep -q 'remoteacc' <<<"$names" && ok "remote account merged" || bad "remoteacc missing"
}

run_row5() {
    step "Row 5 — both edited the same account → conflict"
    require "$ART_DIR/Lc.db" "$ART_DIR/Rc.db"
    cmd_seed "$ART_DIR/Lc.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/Rc.db"
    cmd_unlock; cmd_sync
    local names; names="$(ui dump)"
    grep -q 'test (remote)' <<<"$names" && ok "conflict copy 'test (remote)' created" \
        || bad "no conflict copy"
    grep -qE '^test ' <<<"$names" && ok "local account kept as 'test'" \
        || bad "local 'test' missing"
}

run_row6() {
    step "Row 6 — deletion uploads"
    require "$ART_DIR/DEL.db"
    cmd_seed "$ART_DIR/DEL.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/B0.db"
    cmd_unlock; cmd_sync
    [[ "$(local_md5)" == "$(remote_md5)" ]] && ok "converged" || bad "not converged"
    ui dump | grep -q 'test' && bad "deleted account still present" || ok "deletion propagated"
}

run_row7() {
    step "Row 7 — delete vs edit → keep the edit"
    require "$ART_DIR/Lc.db" "$ART_DIR/DEL.db"
    cmd_seed "$ART_DIR/Lc.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/DEL.db"
    cmd_unlock; cmd_sync
    ui dump | grep -q 'test' && ok "edited account kept" || bad "edit lost"
}

run_row4() {
    step "Row 4 — local edit → upload"
    require "$ART_DIR/Lc.db"
    cmd_seed "$ART_DIR/Lc.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/B0.db"
    cmd_unlock; cmd_sync
    [[ "$(local_md5)" == "$(remote_md5)" ]] && ok "edit uploaded (converged)" \
        || bad "not converged"
    ui dump | grep -q 'test' && ok "account present" || bad "account missing"
}

run_row10() {
    step "Row 10 — password change drops the base"
    cmd_seed "$ART_DIR/B0.db" "$ART_DIR/B0.db"
    cmd_remote "$ART_DIR/B0.db"
    cmd_unlock; cmd_sync
    adb_ shell run-as "$APP_ID" ls files/ | grep -q 'upm.db.sync-base' \
        && ok "precondition: base exists" || bad "base missing before change"
    adb_ shell input keyevent 82; sleep 2
    tap_text "More"; sleep 2
    tap_text "Change Master Password"; sleep 2
    adb_ shell input tap $(ui_find class EditText 0); ui clear; ui type "$(cat "$DB_PASSWORD_FILE")"
    adb_ shell input tap $(ui_find class EditText 1); ui clear; ui type "$(cat "$DB_PASSWORD_FILE")"
    adb_ shell input tap $(ui_find class EditText 2); ui clear; ui type "$(cat "$DB_PASSWORD_FILE")"
    adb_ shell input keyevent 4   # close the IME so OK is tappable
    sleep 1
    tap_text "OK"; sleep 4
    adb_ shell run-as "$APP_ID" ls files/ | grep -q 'upm.db.sync-base' \
        && bad "base not dropped on password change" || ok "base dropped on password change"
}

require() {
    local f
    for f in "$@"; do
        [[ -f "$f" ]] || die "missing $f — create it first (see plan §8 / merge-test.sh usage)"
    done
}

cmd_row() {
    [[ -f "$ART_DIR/B0.db" && -f "$ART_DIR/L1.db" ]] \
        || die "missing artifacts; need $ART_DIR/B0.db and $ART_DIR/L1.db (see plan §8)"
    case "$1" in
        1) run_row1 ;;
        2) run_row2 ;;
        3) run_row3 ;;
        4) run_row4 ;;
        5) run_row5 ;;
        6) run_row6 ;;
        7) run_row7 ;;
        8) run_row8 ;;
        9) run_row9 ;;
        10) run_row10 ;;
        *) die "row $1 is not scripted (needs extra artifacts / UI variants)" ;;
    esac
}

case "${1:-}" in
    up)           cmd_up ;;
    seed)         shift; cmd_seed "$@" ;;
    remote)       shift; cmd_remote "$@" ;;
    unlock)       cmd_unlock ;;
    sync)         cmd_sync ;;
    accounts)     cmd_accounts ;;
    status)       cmd_status ;;
    addaccount)   shift; cmd_addaccount "$@" ;;
    edit)         shift; cmd_edit "$@" ;;
    deleteaccount) shift; cmd_deleteaccount "$@" ;;
    row)          shift; cmd_row "$1" ;;
    all)
        for r in 1 2 4 8 9; do cmd_row "$r"; done
        # extra rows, only when their variant artifacts exist
        for r in 3 5 6 7 10; do
            case "$r" in
                3) [[ -f "$ART_DIR/R2.db" ]] || continue ;;
                5) [[ -f "$ART_DIR/Lc.db" && -f "$ART_DIR/Rc.db" ]] || continue ;;
                6) [[ -f "$ART_DIR/DEL.db" ]] || continue ;;
                7) [[ -f "$ART_DIR/Lc.db" && -f "$ART_DIR/DEL.db" ]] || continue ;;
            esac
            cmd_row "$r"
        done
        printf '\n== summary: %d passed, %d failed ==\n' "$PASS" "$FAIL"
        (( FAIL == 0 )) || exit 1
        ;;
    *) sed -n '3,35p' "$0"; exit 1 ;;
esac

